import crypto from 'node:crypto';

const secret = 'whsec_zealt_test_secret_key_5f2a9c';
const baseUrl = 'http://localhost:5173';

async function runTests() {
  console.log('Starting webhook tests...\n');

  // Test 1: Missing X-Signature-256 header (expect 401)
  try {
    const res = await fetch(`${baseUrl}/webhook`, {
      method: 'POST',
      body: JSON.stringify({ event: 'test', items: [] }),
    });
    console.log(`Test 1 (Missing header): Status = ${res.status} (Expected: 401)`);
    if (res.status !== 401) throw new Error('Test 1 failed');
  } catch (err) {
    console.error(err);
    process.exit(1);
  }

  // Test 2: Invalid signature (expect 401)
  try {
    const res = await fetch(`${baseUrl}/webhook`, {
      method: 'POST',
      headers: {
        'X-Signature-256': 'sha256=invalid_signature_hex_value_here',
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ event: 'test', items: [] }),
    });
    console.log(`Test 2 (Invalid signature): Status = ${res.status} (Expected: 401)`);
    if (res.status !== 401) throw new Error('Test 2 failed');
  } catch (err) {
    console.error(err);
    process.exit(1);
  }

  // Test 3: Valid signature but invalid JSON (expect 400)
  try {
    const invalidJsonBody = '{ "event": "test", "items": ';
    const hmac = crypto.createHmac('sha256', secret);
    hmac.update(invalidJsonBody);
    const signature = 'sha256=' + hmac.digest('hex');

    const res = await fetch(`${baseUrl}/webhook`, {
      method: 'POST',
      headers: {
        'X-Signature-256': signature,
      },
      body: invalidJsonBody,
    });
    console.log(`Test 3 (Invalid JSON): Status = ${res.status} (Expected: 400)`);
    if (res.status !== 400) throw new Error('Test 3 failed');
  } catch (err) {
    console.error(err);
    process.exit(1);
  }

  // Test 4: Valid signature, valid JSON, but incorrect payload structure (missing items) (expect 400)
  try {
    const badPayload = JSON.stringify({ event: 'test' });
    const hmac = crypto.createHmac('sha256', secret);
    hmac.update(badPayload);
    const signature = 'sha256=' + hmac.digest('hex');

    const res = await fetch(`${baseUrl}/webhook`, {
      method: 'POST',
      headers: {
        'X-Signature-256': signature,
        'Content-Type': 'application/json',
      },
      body: badPayload,
    });
    console.log(`Test 4 (Incorrect structure): Status = ${res.status} (Expected: 400)`);
    if (res.status !== 400) throw new Error('Test 4 failed');
  } catch (err) {
    console.error(err);
    process.exit(1);
  }

  // Test 5: Valid signature, valid JSON, correct payload structure (expect 200)
  try {
    const goodPayload = JSON.stringify({ event: 'order_shipped', items: ['item1', 'item2', 'item3'] });
    const hmac = crypto.createHmac('sha256', secret);
    hmac.update(goodPayload);
    const signature = 'sha256=' + hmac.digest('hex');

    const res = await fetch(`${baseUrl}/webhook`, {
      method: 'POST',
      headers: {
        'X-Signature-256': signature,
        'Content-Type': 'application/json',
      },
      body: goodPayload,
    });
    const body = await res.json();
    console.log(`Test 5 (Success): Status = ${res.status} (Expected: 200)`);
    console.log('Response body:', body);
    if (res.status !== 200) throw new Error('Test 5 failed');
    if (body.ok !== true || body.event !== 'order_shipped' || body.count !== 3) {
      throw new Error('Test 5 response body is incorrect');
    }
  } catch (err) {
    console.error(err);
    process.exit(1);
  }

  console.log('\nAll tests passed successfully!');
}

runTests();

